import java.util.Scanner;

public class Main {
    static long[] f = new long[181];
    static long n;
    static long answer;

    static long absolute_value(long x) {
        return x < 0 ? -x : x;
    }

    static void search(int level, long cost) {
        if (n == 0) {
            answer = Math.min(answer, cost);
            return;
        }
        if (level == 0) return;

        for (int i = -10; i <= 10; ++i) {
            long change = i * f[level];
            if (n + change > 0) {
                n += change;
                search(level - 1, cost + absolute_value(i) * level);
                n -= change;
                break;
            }
        }
        for (int i = -10; i <= 10; ++i) {
            long change = i * f[level];
            if (n + change == 0) {
                n += change;
                search(level - 1, cost + absolute_value(i) * level);
                n -= change;
                break;
            }
        }
        for (int i = 10; i >= -10; --i) {
            long change = i * f[level];
            if (n + change < 0) {
                n += change;
                search(level - 1, cost + absolute_value(i) * level);
                n -= change;
                break;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextLong();
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            f[i] = f[i - 1] * 10 + 1;
        }
        answer = Long.MAX_VALUE;
        search(16, 0);
        System.out.println(answer);
        scanner.close();
    }
}
